// scan.Mapper[*T] without reflection: maps columns to fields by index.
func providerCredentialScanMapper(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*ProviderCredential, error)) {
	// resolve the column positions once per query, not per row
	type target struct {
		idx int
		dst func(o *ProviderCredential) any
	}
	targets := make([]target, 0, 19)
	for i, col := range cols {
		switch col {
		case "id":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.ID }})
		case "provider":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.Provider }})
		case "label":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.Label }})
		case "base_url":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.BaseURL }})
		case "ciphertext":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.Ciphertext }})
		case "nonce":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.Nonce }})
		case "enabled":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.Enabled }})
		case "created_at":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.CreatedAt }})
		case "updated_at":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.UpdatedAt }})
		case "last_checked_at":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.LastCheckedAt }})
		case "last_error":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.LastError }})
		case "manual_models_json":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.ManualModelsJSON }})
		case "access_mode":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.AccessMode }})
		case "subscription_fee_pico_usd":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.SubscriptionFeePicoUsd }})
		case "subscription_cycle_start":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.SubscriptionCycleStart }})
		case "subscription_cycle_end":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.SubscriptionCycleEnd }})
		case "subscription_status":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.SubscriptionStatus }})
		case "next_available_at":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.NextAvailableAt }})
		case "status_reason":
			targets = append(targets, target{i, func(o *ProviderCredential) any { return &o.StatusReason }})
		}
	}

	return func(row *scan.Row) (any, error) {
			o := new(ProviderCredential)
			for _, t := range targets {
				row.ScheduleScanByIndex(t.idx, t.dst(o))
			}
			return o, nil
		}, func(v any) (*ProviderCredential, error) {
			return v.(*ProviderCredential), nil
		}
}

// FindProviderCredential retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindProviderCredential(ctx context.Context, exec bob.Executor, IDPK string, cols ...string) (*ProviderCredential, error) {
	if len(cols) == 0 {
		return ProviderCredentials.Query(
			sm.Where(ProviderCredentials.Columns.ID.EQ(sqlite.Arg(IDPK))),
		).One(ctx, exec)
	}

	return ProviderCredentials.Query(
		sm.Where(ProviderCredentials.Columns.ID.EQ(sqlite.Arg(IDPK))),
		sm.Columns(ProviderCredentials.Columns.Only(cols...)),
	).One(ctx, exec)
}

// ProviderCredentialExists checks the presence of a single record by primary key
func ProviderCredentialExists(ctx context.Context, exec bob.Executor, IDPK string) (bool, error) {
	return ProviderCredentials.Query(
		sm.Where(ProviderCredentials.Columns.ID.EQ(sqlite.Arg(IDPK))),
	).Exists(ctx, exec)
}

