func (o *ProviderCredential) pkEQ() dialect.Expression {
	return sqlite.Quote("provider_credentials", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		return o.primaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

